# Golden values for phn-epi two_by_two.rs. Run: Rscript two_by_two.R > two_by_two.json
suppressPackageStartupMessages({library(epitools); library(jsonlite)})
tables <- list(c(30,10,5,25), c(12,3,7,18), c(5,7,9,11), c(1,9,4,6), c(45,155,30,270),
               c(3,0,8,9), c(0,10,6,4), c(17,21,8,40), c(250,750,100,900), c(2,3,1,8))
cases <- lapply(tables, function(v) {
  a<-v[1]; b<-v[2]; c<-v[3]; d<-v[4]
  m <- matrix(c(a,b,c,d), nrow=2, byrow=TRUE)
  ft <- fisher.test(m)
  ft_g <- fisher.test(m, alternative="greater"); ft_l <- fisher.test(m, alternative="less")
  out <- list(a=a,b=b,c=c,d=d, fisher_two_sided=ft$p.value, fisher_greater=ft_g$p.value,
              fisher_less=ft_l$p.value, or_mle=unname(ft$estimate),
              or_exact_lower=ft$conf.int[1], or_exact_upper=if (is.finite(ft$conf.int[2])) ft$conf.int[2] else NULL)
  if (all(c(a,b,c,d) > 0)) {
    w <- oddsratio(m[2:1,2:1], method="wald")  # epitools wants unexposed/non-case first
    out$or_woolf <- w$measure[2,1]; out$or_woolf_lower <- w$measure[2,2]; out$or_woolf_upper <- w$measure[2,3]
  }
  if (a > 0 && c > 0) {
    r <- riskratio(m[2:1,2:1], method="wald")
    out$rr <- r$measure[2,1]; out$rr_lower <- r$measure[2,2]; out$rr_upper <- r$measure[2,3]
  }
  mp <- tryCatch(oddsratio(m[2:1,2:1], method="midp"), error=function(e) NULL)
  if (!is.null(mp) && is.finite(mp$measure[2,3]) && mp$measure[2,2] > 0) {
    out$or_midp_lower <- mp$measure[2,2]; out$or_midp_upper <- mp$measure[2,3]
  }
  E <- outer(rowSums(m), colSums(m))/sum(m)
  if (all(E > 0)) {
    out$chisq <- unname(suppressWarnings(chisq.test(m, correct=FALSE))$statistic)
    out$chisq_yates <- unname(suppressWarnings(chisq.test(m, correct=TRUE))$statistic)
    out$chisq_yates_p <- suppressWarnings(chisq.test(m, correct=TRUE))$p.value
  }
  out
})
strat <- list(
  list(c(20,80,10,90), c(40,60,25,75)),
  list(c(12,18,6,24), c(9,11,4,16), c(30,70,12,88)),
  list(c(5,95,2,98), c(15,35,10,40), c(8,12,3,17), c(2,4,1,9))
)
scases <- lapply(strat, function(s) {
  arr <- array(unlist(lapply(s, function(v) matrix(v, 2, byrow=TRUE))), dim=c(2,2,length(s)))
  mh <- mantelhaen.test(arr, correct=TRUE)
  list(strata=lapply(s, as.list), mh_or=unname(mh$estimate), mh_or_lower=mh$conf.int[1],
       mh_or_upper=mh$conf.int[2], mh_stat=unname(mh$statistic), mh_p=mh$p.value)
})
cat(toJSON(list(note="Generated by R with epitools (oddsratio wald/midp, riskratio wald), fisher.test, chisq.test, mantelhaen.test; generator: tests/fixtures/generators/two_by_two.R, then two_by_two_statsmodels.py adds Breslow-Day and the MH risk ratio.",
                r_version=R.version.string, tables=cases, stratified=scases), auto_unbox=TRUE, digits=NA, pretty=TRUE))
